CREATE TABLE ibexa_media (contentobject_attribute_id INTEGER DEFAULT 0 NOT NULL, version INTEGER DEFAULT 0 NOT NULL, controls VARCHAR(50) DEFAULT NULL, filename VARCHAR(255) DEFAULT '' NOT NULL, has_controller INTEGER DEFAULT 0, height INTEGER DEFAULT NULL, is_autoplay INTEGER DEFAULT 0, is_loop INTEGER DEFAULT 0, mime_type VARCHAR(50) DEFAULT '' NOT NULL, original_filename VARCHAR(255) DEFAULT '' NOT NULL, pluginspage VARCHAR(255) DEFAULT NULL, quality VARCHAR(50) DEFAULT NULL, width INTEGER DEFAULT NULL, PRIMARY KEY(contentobject_attribute_id, version));
